    {
      "fact_key": "北京银行西单支行账户实际余额",
      "value": "北京银行西单支行账户实际余额为101.17元，银行归集金额为12,209,446,294.50元",
      "doc_id": "kdx_inquiry_2019",
      "quote": "最终结果即实际余额101.17元，银行归集金额为12,209,446,294.50元"
